given.script:
%dw 2.0
type ClickEvent = { x: Number, y: Number }
type KeyEvent = { key: String }
output application/json
---
{
  clickFirst: if ({x:1,y:2,key:"Enter"} is ClickEvent) "Click" else if ({x:1,y:2,key:"Enter"} is KeyEvent) "Key" else "Unknown",
  keyFirst: if ({x:1,y:2,key:"Enter"} is KeyEvent) "Key" else if ({x:1,y:2,key:"Enter"} is ClickEvent) "Click" else "Unknown"
}

